<?php
require_once(__DIR__ . '/../../config.php');
use local_kbacompany\local\competency_assessment_service;
require_login();
$context=context_system::instance(); require_capability('local/kbacompany:viewowncompany',$context);
$uuid=required_param('uuid',PARAM_RAW_TRIMMED); $userid=required_param('userid',PARAM_INT);
$assessmentuuid=optional_param('assessment','',PARAM_RAW_TRIMMED); $action=optional_param('action','',PARAM_ALPHA);
if ($action==='create') { require_sesskey(); $assessmentuuid=competency_assessment_service::create($uuid,$userid,(int)$USER->id,required_param('method',PARAM_ALPHANUMEXT)); redirect(new moodle_url('/local/kbacompany/competency_assessment.php',['uuid'=>$uuid,'userid'=>$userid,'assessment'=>$assessmentuuid])); }
if ($assessmentuuid!=='' && $action==='save') { require_sesskey(); competency_assessment_service::save_item($uuid,$assessmentuuid,(int)$USER->id,required_param('itemid',PARAM_INT),required_param('proposedlevel',PARAM_INT),optional_param('evidence','',PARAM_TEXT),optional_param('evidenceurl','',PARAM_URL),optional_param('rationale','',PARAM_TEXT)); redirect(new moodle_url('/local/kbacompany/competency_assessment.php',['uuid'=>$uuid,'userid'=>$userid,'assessment'=>$assessmentuuid])); }
if ($assessmentuuid!=='' && $action==='submit') { require_sesskey(); competency_assessment_service::submit($uuid,$assessmentuuid,(int)$USER->id); redirect(new moodle_url('/local/kbacompany/competency_assessment.php',['uuid'=>$uuid,'userid'=>$userid,'assessment'=>$assessmentuuid]),get_string('assessment_submitted','local_kbacompany')); }
if ($assessmentuuid!=='' && in_array($action,['approve','reject'],true)) { require_sesskey(); competency_assessment_service::decide($uuid,$assessmentuuid,(int)$USER->id,$action==='approve',optional_param('decisionnote','',PARAM_TEXT)); redirect(new moodle_url('/local/kbacompany/competency_assessment.php',['uuid'=>$uuid,'userid'=>$userid,'assessment'=>$assessmentuuid]),get_string($action==='approve'?'assessment_approved':'assessment_rejected','local_kbacompany')); }
$PAGE->set_context($context); $PAGE->set_url(new moodle_url('/local/kbacompany/competency_assessment.php',['uuid'=>$uuid,'userid'=>$userid,'assessment'=>$assessmentuuid])); $PAGE->set_title(get_string('assessment_title','local_kbacompany')); $PAGE->set_heading(get_string('pluginname','local_kbacompany'));
$shell=\local_kbacompany\local\bms_page_shell_service::begin($uuid,(int)$USER->id,'employees',get_string('assessment_title','local_kbacompany'));
echo html_writer::div(html_writer::link(new moodle_url('/local/kbacompany/employee_competencies.php',['uuid'=>$uuid,'userid'=>$userid]),'← '.get_string('employeecompetency_title','local_kbacompany')),'mb-3');
if ($assessmentuuid==='') {
    $profile=\local_kbacompany\local\employee_competency_profile_service::context($uuid,$userid,(int)$USER->id); echo $OUTPUT->heading(s($profile['employee']['full_name']),2);
    echo html_writer::tag('p',get_string('assessment_intro','local_kbacompany'),['class'=>'text-muted']);
    if ($profile['can_manage'] && $profile['position_profile']) { $f=html_writer::start_tag('form',['method'=>'post','class'=>'form-inline mb-3']); foreach(['uuid'=>$uuid,'userid'=>$userid,'action'=>'create','sesskey'=>sesskey()] as $n=>$v){$f.=html_writer::empty_tag('input',['type'=>'hidden','name'=>$n,'value'=>$v]);} $opts=''; foreach(competency_assessment_service::methods() as $m){$opts.=html_writer::tag('option',get_string('assessment_method_'.$m,'local_kbacompany'),['value'=>$m]);} $f.=html_writer::tag('select',$opts,['name'=>'method','class'=>'form-control mr-2']).html_writer::tag('button',get_string('assessment_create','local_kbacompany'),['type'=>'submit','class'=>'btn btn-primary']).html_writer::end_tag('form'); echo $f; }
    $t=new html_table(); $t->head=[get_string('assessment_method','local_kbacompany'),get_string('status'),get_string('assessment_created','local_kbacompany'),get_string('actions')]; foreach(competency_assessment_service::list_for_employee($uuid,$userid,(int)$USER->id) as $r){$url=new moodle_url('/local/kbacompany/competency_assessment.php',['uuid'=>$uuid,'userid'=>$userid,'assessment'=>$r['uuid']]);$t->data[]=[get_string('assessment_method_'.$r['method'],'local_kbacompany'),get_string('assessment_status_'.$r['status'],'local_kbacompany'),userdate($r['timecreated']),html_writer::link($url,get_string('open'))];} echo html_writer::div(html_writer::table($t),'table-responsive');
} else {
    $d=competency_assessment_service::context($uuid,$assessmentuuid,(int)$USER->id); $a=$d['assessment']; echo $OUTPUT->heading(s($d['employee']['full_name']),2); echo html_writer::tag('p',get_string('assessment_context','local_kbacompany',(object)['method'=>get_string('assessment_method_'.$a->method,'local_kbacompany'),'status'=>get_string('assessment_status_'.$a->status,'local_kbacompany')]),['class'=>'text-muted']);
    foreach($d['items'] as $i){echo html_writer::start_div('card mb-2'); echo html_writer::start_div('card-body'); echo html_writer::tag('h5',s($i['name'])); echo html_writer::tag('p',get_string('assessment_target','local_kbacompany').': '.(int)$i['targetlevel'],['class'=>'small text-muted']); if($d['can_edit']){$f=html_writer::start_tag('form',['method'=>'post']); foreach(['uuid'=>$uuid,'userid'=>$userid,'assessment'=>$assessmentuuid,'action'=>'save','itemid'=>$i['id'],'sesskey'=>sesskey()] as $n=>$v){$f.=html_writer::empty_tag('input',['type'=>'hidden','name'=>$n,'value'=>$v]);}$f.=html_writer::tag('label',get_string('assessment_proposed_level','local_kbacompany')).html_writer::empty_tag('input',['type'=>'number','min'=>0,'max'=>100,'name'=>'proposedlevel','value'=>$i['proposedlevel'],'class'=>'form-control mb-2']).html_writer::tag('label',get_string('employeecompetency_evidence','local_kbacompany')).html_writer::tag('textarea',s($i['evidence']),['name'=>'evidence','class'=>'form-control mb-2','rows'=>2]).html_writer::tag('label',get_string('employeecompetency_evidence_url','local_kbacompany')).html_writer::empty_tag('input',['type'=>'url','name'=>'evidenceurl','value'=>$i['evidenceurl'],'class'=>'form-control mb-2']).html_writer::tag('label',get_string('assessment_rationale','local_kbacompany')).html_writer::tag('textarea',s($i['rationale']),['name'=>'rationale','class'=>'form-control mb-2','rows'=>2]).html_writer::tag('button',get_string('savechanges'),['type'=>'submit','class'=>'btn btn-sm btn-primary']).html_writer::end_tag('form');echo $f;}else{echo html_writer::tag('p',get_string('assessment_proposed_level','local_kbacompany').': '.(int)$i['proposedlevel']); if($a->status==='approved')echo html_writer::tag('p',get_string('assessment_decided_level','local_kbacompany').': '.(int)$i['decidedlevel'],['class'=>'font-weight-bold']);} echo html_writer::end_div().html_writer::end_div();}
    if($d['can_edit']){echo html_writer::link(new moodle_url('/local/kbacompany/competency_assessment.php',['uuid'=>$uuid,'userid'=>$userid,'assessment'=>$assessmentuuid,'action'=>'submit','sesskey'=>sesskey()]),get_string('assessment_submit','local_kbacompany'),['class'=>'btn btn-success']);}
    if($d['can_decide']){$f=html_writer::start_tag('form',['method'=>'post','class'=>'mt-3']);foreach(['uuid'=>$uuid,'userid'=>$userid,'assessment'=>$assessmentuuid,'sesskey'=>sesskey()] as $n=>$v){$f.=html_writer::empty_tag('input',['type'=>'hidden','name'=>$n,'value'=>$v]);}$f.=html_writer::tag('label',get_string('assessment_decision_note','local_kbacompany')).html_writer::tag('textarea','',['name'=>'decisionnote','class'=>'form-control mb-2','rows'=>2]).html_writer::tag('button',get_string('assessment_approve','local_kbacompany'),['name'=>'action','value'=>'approve','type'=>'submit','class'=>'btn btn-success mr-2']).html_writer::tag('button',get_string('assessment_reject','local_kbacompany'),['name'=>'action','value'=>'reject','type'=>'submit','class'=>'btn btn-outline-danger']).html_writer::end_tag('form');echo $f;}
}
\local_kbacompany\local\bms_page_shell_service::finish($shell);
